/**
 * ChevronIcon — returns an SVG element used as the expand/collapse indicator.
 */
function ChevronIcon() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 20 20");
  svg.setAttribute("fill", "none");
  svg.setAttribute("stroke", "currentColor");
  svg.setAttribute("stroke-width", "2");
  svg.setAttribute("stroke-linecap", "round");
  svg.setAttribute("stroke-linejoin", "round");
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("focusable", "false");
  svg.classList.add("chevron");

  const path = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
  path.setAttribute("points", "4 7 10 13 16 7");
  svg.appendChild(path);
  return svg;
}

/**
 * DisclosureTrigger — wraps the question text + chevron in a <button>
 * inside an <h3>, wired up for expand/collapse behaviour.
 */
function DisclosureTrigger({ id, question, panelEl }) {
  const heading = document.createElement("h3");

  const button = document.createElement("button");
  button.type = "button";
  button.setAttribute("aria-expanded", "false");
  button.setAttribute("aria-controls", id);

  const label = document.createTextNode(question);
  button.appendChild(label);
  button.appendChild(ChevronIcon());

