  button.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
      button.setAttribute("aria-expanded", "false");
      panelEl.hidden = true;
      button.focus();
    }
  });

  heading.appendChild(button);
  return heading;
}

