    const seen = new Set();
    const violations = [];
    for (const r of runs) {
      for (const v of r.violations) {
        if (!seen.has(v.id)) { seen.add(v.id); violations.push(v); }
      }
    }
    return violations;
  };

  const all = merge([collapsed, expanded]);
  const wcag = all.filter(v => !v.tags.includes('best-practice'));
  const bp   = all.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description,
      nodes: v.nodes.map(n => ({ target: n.target, html: n.html.slice(0,120) })) })),
    bp:   bp.map(v => ({ id: v.id,
      nodes: v.nodes.map(n => ({ target: n.target })) }))
  }, null, 2));

  process.exit(wcag.length ? 1 : 0);
})();
