*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:          #0d0d14;
  --surface:     #17172b;
  --surface-alt: #1f1f38;
  --border:      #2e2e52;
  --accent:      #a78bfa;
  --accent-dim:  #7c5ce0;
  --text:        #e2e0f0;
  --text-muted:  #9490b5;
  --focus-ring:  #a78bfa;
  --radius:      10px;
  --transition:  200ms ease;
}

/* ── Forced-colors / high-contrast ───────────────────────────── */
@media (forced-colors: active) {
  :root {
    --bg: Canvas;
    --surface: Canvas;
    --surface-alt: Canvas;
    --border: ButtonText;
    --accent: Highlight;
    --text: CanvasText;
    --text-muted: CanvasText;
    --focus-ring: Highlight;
  }
}

/* ── Skip link ───────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #0d0d14;
  font-weight: 700;
  border-radius: var(--radius);
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Page ────────────────────────────────────────────────────── */
html { font-size: 100%; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.65;
  min-height: 100dvh;
  padding: 0 1rem 4rem;
}

/* ── Header ──────────────────────────────────────────────────── */
.site-header {
  text-align: center;
  padding: 3.5rem 1rem 2.5rem;
}
.site-header .cat-icon {
  font-size: 3.25rem;
  display: block;
  margin-bottom: 0.5rem;
  line-height: 1;
}
.site-header h1 {
  font-size: clamp(1.75rem, 5vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--accent);
}
.site-header p {
  margin-top: 0.6rem;
  color: var(--text-muted);
  font-size: 1.05rem;
  max-width: 38ch;
  margin-inline: auto;
}

/* ── FAQ list ────────────────────────────────────────────────── */
.faq-list {
  max-width: 720px;
  margin-inline: auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Example wrapper (each Q&A) ──────────────────────────────── */
.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.example:has(button[aria-expanded="true"]) {
  border-color: var(--accent-dim);
  box-shadow: 0 0 0 1px var(--accent-dim), 0 4px 24px rgba(124, 92, 224, 0.18);
}

/* ── Trigger heading ─────────────────────────────────────────── */
.example h2 { margin: 0; }

.example h2 button {
  all: unset;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.1rem 1.4rem;
  cursor: pointer;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  background: transparent;
  text-align: left;
  transition: background var(--transition), color var(--transition);
}
.example h3 button:hover {
  background: var(--surface-alt);
  color: var(--accent);
}
.example h3 button:focus-visible {
  outline: 2.5px solid var(--focus-ring);
  outline-offset: -2.5px;
  border-radius: calc(var(--radius) - 1px);
  color: var(--accent);
}

/* ── Chevron icon ────────────────────────────────────────────── */
.example h3 button .chevron {
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  color: var(--text-muted);
  transition: transform var(--transition), color var(--transition);
}
.example h3 button[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
  color: var(--accent);
}

/* ── Answer panel ────────────────────────────────────────────── */
.details {
  padding: 0 1.4rem 1.25rem;
  border-top: 1px solid var(--border);
  animation: slideDown 180ms ease both;
}
.details p {
  color: var(--text-muted);
  font-size: 0.97rem;
  line-height: 1.7;
  padding-top: 0.85rem;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Reduced motion ──────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}

/* ── Reflow / narrow viewports ───────────────────────────────── */
@media (max-width: 360px) {
  .example h3 button { padding: 0.9rem 1rem; font-size: 0.97rem; }
  .details           { padding: 0 1rem 1rem; }
}
